import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const a = second.split(" ").map(Number);
const n = a.length;

// 交換回数は「i < j かつ Ai > Aj となる組」の個数（転倒数）に等しい
let swaps = 0;
for (let i = 0; i < n; i++) {
  for (let j = i + 1; j < n; j++) {
    if (a[i] > a[j]) swaps++;
  }
}
console.log(swaps);
